/* Bonnyrigg Tiles site script: enquiry cart, Build Your Brief, quick view, carousel, sale notice, 3D slab, tile visualiser.
   Paste this whole file into the site JS box. It runs once per page and waits for the page to be ready. */
(function(){
function btBoot(){
/* Bonnyrigg Tiles: enquiry cart + header behaviour (bt-site.js, part 1 of 3)
   Storage: localStorage key "bt_enquiry_cart_v1" holds a JSON array of lines:
   { id, url, title, brand, kicker, variantLabel, variant:{colour,finish,size,other}, sku,
     qtyType:"m2"|"units"|"sample", m2, m2PerBox, wastage, boxes, units,
     unitPrice|null, priceHidden, note }
   Add to cart from any page:  <a href="/product/" data-bt-add='{"title":"...", ...}'>Add to enquiry</a>
   or from script:             window.BTCart.add({...})
   All listeners are delegated from document, so they survive a builder re-render. */
(function(){
  if(window.__btSite){return;} window.__btSite=1;
  document.documentElement.classList.add('bt-js');
  var KEY='bt_enquiry_cart_v1', mem=[], store=null;
  try{localStorage.setItem('__bt_t','1');localStorage.removeItem('__bt_t');store=localStorage;}catch(e){store=null;}

  function read(){
    if(!store){return mem.slice();}
    try{var r=JSON.parse(store.getItem(KEY)||'[]');return Array.isArray(r)?r:[];}catch(e){return mem.slice();}
  }
  function write(lines){
    mem=lines.slice();
    if(store){try{store.setItem(KEY,JSON.stringify(lines));}catch(e){}}
    for(var i=0;i<subs.length;i++){try{subs[i](lines);}catch(e){}}
  }
  var subs=[];
  function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function money(n){var p=(Math.round(n*100)/100).toFixed(2).split('.');return '$'+p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+p[1];}
  function num(n){return (Math.round(n*100)/100).toString();}
  function all(sel){return Array.prototype.slice.call(document.querySelectorAll(sel));}
  function find(lines,id){for(var i=0;i<lines.length;i++){if(lines[i].id===id){return i;}}return -1;}

  /* box and estimate maths for one line */
  function calc(l){
    var o={boxes:0,cover:0,est:null,priced:!l.priceHidden&&typeof l.unitPrice==='number'};
    if(l.qtyType==='m2'){
      var area=parseFloat(l.m2); if(!(area>0)){return o;}
      if(l.wastage){area=area*1.1;}
      var per=parseFloat(l.m2PerBox);
      if(per>0){o.boxes=Math.ceil(area/per-1e-9);o.cover=o.boxes*per;}else{o.cover=area;}
      if(o.priced){o.est=o.cover*l.unitPrice;}
    }else if(l.qtyType==='units'){
      var u=parseInt(l.units,10)||0; if(o.priced){o.est=u*l.unitPrice;}
    }
    return o;
  }
  function calcText(l){
    var c=calc(l);
    if(l.qtyType==='sample'){return 'Sample request';}
    if(l.qtyType==='m2'){
      if(!(parseFloat(l.m2)>0)){return 'Enter your area for a box count'+(c.priced?' and estimate':'')+'.';}
      var t=c.boxes?('<b>'+c.boxes+(c.boxes===1?' box':' boxes')+'</b> covering '+num(c.cover)+' m²'):(num(c.cover)+' m²');
      return t+(c.priced?' · about <b>'+money(c.est)+'</b>':(l.priceHidden?' · price on enquiry':''));
    }
    return c.priced?('About <b>'+money(c.est)+'</b>'):(l.priceHidden?'Price on enquiry':'');
  }
  function priceText(l){
    if(l.priceHidden||typeof l.unitPrice!=='number'){return 'Price on enquiry';}
    return (l.priceFrom?'From ':'')+money(l.unitPrice)+(l.qtyType==='m2'?' per m²':' each');
  }
  function lineHtml(l){
    var meta=[l.variantLabel,l.note].filter(Boolean).map(esc).join(' · ');
    var h='<li class="bt-line" data-bt-line="'+esc(l.id)+'"><span class="bt-line-img">'+(l.img?'<img src="'+esc(l.img)+'" alt="'+esc(l.title)+' swatch" width="104" height="104">':'')+'</span><div class="bt-line-top"><div>'+
      (l.kicker?'<p class="bt-line-k">'+esc(l.kicker)+'</p>':'')+
      '<a class="bt-line-title" href="'+esc(l.url||'#')+'">'+esc(l.title)+'</a></div>'+
      '<button type="button" class="bt-line-x" data-bt-remove aria-label="Remove '+esc(l.title)+' from enquiry"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5l14 14M19 5L5 19"/></svg></button></div>'+
      '<p class="bt-line-meta">'+(meta?meta+' · ':'')+esc(priceText(l))+'</p>';
    if(l.qtyType==='m2'){
      h+='<div class="bt-line-qty"><label class="bt-field">Area m² <input type="number" inputmode="decimal" min="0" step="0.5" placeholder="e.g. 12" value="'+(parseFloat(l.m2)>0?esc(l.m2):'')+'" data-bt-m2></label>'+
         '<label class="bt-check"><input type="checkbox" data-bt-waste'+(l.wastage?' checked':'')+'> Add 10% for cuts and wastage</label></div>';
    }else if(l.qtyType==='units'){
      h+='<div class="bt-line-qty"><span class="bt-field">Quantity</span><span class="bt-stepper"><button type="button" data-bt-step="-1" aria-label="Decrease quantity">−</button><output>'+(parseInt(l.units,10)||1)+'</output><button type="button" data-bt-step="1" aria-label="Increase quantity">+</button></span></div>';
    }
    return h+'<p class="bt-line-calc" data-bt-calc>'+calcText(l)+'</p></li>';
  }
  function totals(lines){
    var sum=0,any=false,unpriced=0;
    for(var i=0;i<lines.length;i++){var c=calc(lines[i]);if(c.est!=null){sum+=c.est;any=true;}else{unpriced++;}}
    all('[data-bt-cart-total]').forEach(function(n){n.textContent=any?money(sum):'On enquiry';});
    all('[data-bt-cart-fine]').forEach(function(n){
      n.textContent='Estimate only. Final pricing confirmed by our team.'+(any&&unpriced?' '+unpriced+(unpriced===1?' item is':' items are')+' not included in this estimate yet.':'');
    });
  }
  function badges(lines){
    var n=lines.length;
    all('[data-bt-cart-count]').forEach(function(b){b.textContent=n;b.hidden=!n;});
    all('[data-bt-cart-items]').forEach(function(b){b.textContent=n?(n+(n===1?' item':' items')):'';});
  }
  function render(){
    var lines=read();
    badges(lines);
    all('[data-bt-cart-lines]').forEach(function(ul){ul.innerHTML=lines.map(lineHtml).join('');});
    all('[data-bt-cart-empty]').forEach(function(n){n.hidden=!!lines.length;});
    all('[data-bt-cart-foot]').forEach(function(n){n.hidden=!lines.length;});
    all('[data-bt-cart-summary]').forEach(function(ul){ul.innerHTML=lines.map(sumHtml).join('');});
    totals(lines);
    fields(lines);
  }
  /* compact read-only line for the checkout summary and the thank you page */
  function qtyText(l){
    var c=calc(l);
    if(l.qtyType==='sample'){return 'Sample request';}
    if(l.qtyType==='m2'){
      if(!(parseFloat(l.m2)>0)){return 'Area to be confirmed';}
      return num(l.m2)+' m²'+(l.wastage?' plus 10% for cuts':'')+(c.boxes?', '+c.boxes+(c.boxes===1?' box':' boxes'):'');
    }
    return 'Quantity '+(parseInt(l.units,10)||1);
  }
  function sumHtml(l){
    var c=calc(l), meta=[l.variantLabel,l.note].filter(Boolean).map(esc).join(' · ');
    return '<li class="bt-sum-line"><span class="bt-line-img">'+(l.img?'<img src="'+esc(l.img)+'" alt="'+esc(l.title)+' swatch" width="104" height="104">':'')+'</span>'+
      '<div><p class="bt-sum-t">'+esc(l.title)+'</p>'+(meta?'<p class="bt-sum-m">'+meta+'</p>':'')+'<p class="bt-sum-q">'+esc(qtyText(l))+'</p></div>'+
      '<b class="bt-sum-e">'+(c.est!=null?money(c.est):(l.priceHidden?'On enquiry':esc(priceText(l))))+'</b></li>';
  }
  /* plain text copy of the cart for the form fields the platform emails through */
  function linesText(lines,sep){
    return lines.map(function(l,i){
      var c=calc(l), bits=[(i+1)+'. '+l.title]; if(l.variantLabel){bits.push(l.variantLabel);}
      bits.push(qtyText(l)); if(c.est!=null){bits.push('about '+money(c.est));}else if(l.priceHidden){bits.push('price on enquiry');}
      if(l.note){bits.push(l.note);} if(l.sku){bits.push('SKU '+l.sku);}
      return bits.join(', ');
    }).join(sep||'\n');
  }
  function estTotal(lines){var sum=0,any=false;for(var i=0;i<lines.length;i++){var c=calc(lines[i]);if(c.est!=null){sum+=c.est;any=true;}}return any?money(sum):'On enquiry';}
  function fields(lines){
    all('[data-bt-enquiry-items]').forEach(function(i){i.value=linesText(lines);});
    all('[data-bt-enquiry-total]').forEach(function(i){i.value=lines.length?estTotal(lines):'';});
    all('[data-bt-enquiry-count]').forEach(function(i){i.value=lines.length||'';});
  }
  function refreshLine(id){
    var lines=read(),i=find(lines,id); if(i<0){return;}
    all('[data-bt-line]').forEach(function(li){
      if(li.getAttribute('data-bt-line')===id){
        var c=li.querySelector('[data-bt-calc]'); if(c){c.innerHTML=calcText(lines[i]);}
        var o=li.querySelector('output'); if(o){o.textContent=parseInt(lines[i].units,10)||1;}
      }
    });
    totals(lines);
  }

  /* cart operations */
  function add(item){
    if(!item||!item.title){return null;}
    var l={
      id:item.id||((item.sku||item.url||item.title)+(item.variantLabel?'|'+item.variantLabel:'')+(item.qtyType==='sample'?'|sample':'')),
      url:item.url||'',title:item.title,brand:item.brand||'',kicker:item.kicker||'',
      variantLabel:item.variantLabel||'',variant:item.variant||{},sku:item.sku||'',
      qtyType:item.qtyType||'units',m2:item.m2!=null?item.m2:null,m2PerBox:item.m2PerBox!=null?item.m2PerBox:null,
      wastage:!!item.wastage,boxes:0,units:item.units!=null?item.units:(item.qtyType==='units'||!item.qtyType?1:null),
      unitPrice:(typeof item.unitPrice==='number'&&!item.priceHidden)?item.unitPrice:null,
      priceFrom:!!item.priceFrom,priceHidden:!!item.priceHidden,note:item.note||'',
      img:(typeof item.img==='string'&&item.img.length<9000&&/^(data:image\/|https:\/\/|\/)/.test(item.img))?item.img:''
    };
    l.boxes=calc(l).boxes;
    var lines=read(),i=find(lines,l.id);
    if(i>=0){ if(lines[i].qtyType==='units'){lines[i].units=(parseInt(lines[i].units,10)||0)+(parseInt(l.units,10)||1);} }
    else{ lines.push(l); }
    write(lines); render(); return l.id;
  }
  function update(id,patch){
    var lines=read(),i=find(lines,id); if(i<0){return;}
    for(var k in patch){if(Object.prototype.hasOwnProperty.call(patch,k)){lines[i][k]=patch[k];}}
    lines[i].boxes=calc(lines[i]).boxes;
    write(lines);
  }
  function remove(id){var lines=read(),i=find(lines,id);if(i>=0){lines.splice(i,1);write(lines);}render();}
  function clear(){write([]);render();}

  /* drawer + overlays */
  function toggle(cls){return document.querySelector('.bt-header .'+cls);}
  function lock(){
    var on=!!document.querySelector('.bt-header .bt-cart-toggle:checked, .bt-header .bt-nav-toggle:checked, .bt-header .bt-brief-toggle:checked');
    document.documentElement.classList.toggle('bt-lock',on);
  }
  var lastFocus=null;
  function flash(msg){
    all('[data-bt-cart-flash]').forEach(function(f){
      f.textContent=msg;f.hidden=false;clearTimeout(f.__t);f.__t=setTimeout(function(){f.hidden=true;},3200);
    });
  }
  function open(msg){
    var t=toggle('bt-cart-toggle'); if(!t){return false;}
    lastFocus=document.activeElement;
    render(); t.checked=true; lock();
    if(msg){flash(msg);}
    setTimeout(function(){var c=document.querySelector('.bt-header [data-bt-cart-close]');if(c){c.focus();}},60);
    return true;
  }
  function close(){
    var t=toggle('bt-cart-toggle'); if(t&&t.checked){t.checked=false;lock();if(lastFocus&&lastFocus.focus){try{lastFocus.focus();}catch(e){}}}
  }
  /* build your brief sidebar */
  function briefSync(){
    var lines=read(), txt=lines.map(function(l){
      var c=calc(l), bits=[l.title]; if(l.variantLabel){bits.push(l.variantLabel);}
      if(l.m2){bits.push(l.m2+' m2'+(c.boxes?' ('+c.boxes+' boxes)':''));}else if(l.units){bits.push('qty '+l.units);}
      return bits.join(', ');
    }).join(' | ');
    all('[data-bt-brief-cart]').forEach(function(i){i.value=txt;});
    all('[data-bt-brief-cartnote]').forEach(function(n){
      n.hidden=!lines.length;
      n.textContent=lines.length?('Your enquiry cart ('+lines.length+(lines.length===1?' item':' items')+') will be sent with this brief.'):'';
    });
  }
  /* keep the brief consistent: clear answers that no longer apply to the chosen space or needs */
  function briefPrune(form){
    function clear(root){
      Array.prototype.slice.call(root.querySelectorAll('input')).forEach(function(i){
        if(i.type==='checkbox'||i.type==='radio'){i.checked=false;}else if(i.type==='number'){i.value='';}
      });
    }
    var p=form.querySelector('.bt-p:checked'), k=p?p.getAttribute('data-k'):null;
    if(k){Array.prototype.slice.call(form.querySelectorAll('.bt-no-'+k)).forEach(clear);}
    if(k!=='out'){Array.prototype.slice.call(form.querySelectorAll('label.bt-only-out')).forEach(clear);}
    Array.prototype.slice.call(form.querySelectorAll('.bt-d[data-need]')).forEach(function(d){
      var n=form.querySelector('.bt-nd-'+d.getAttribute('data-need')); if(!n||!n.checked){clear(d);}
    });
  }
  function briefOpen(){
    var t=toggle('bt-brief-toggle'); if(!t){return false;}
    lastFocus=document.activeElement; t.checked=true; lock(); briefSync();
    setTimeout(function(){var c=document.querySelector('.bt-header .bt-brief-panel .bt-x');if(c){c.focus();}},80);
    return true;
  }
  function lineId(el){var li=el.closest('[data-bt-line]');return li?li.getAttribute('data-bt-line'):null;}

  document.addEventListener('click',function(e){
    var t=e.target; if(!t||!t.closest){return;}
    var a=t.closest('[data-bt-add]');
    if(a){
      var item=null; try{item=JSON.parse(a.getAttribute('data-bt-add'));}catch(err){}
      if(item){
        /* inside a quick view or product block, pick up the chosen size and area */
        var prod=a.closest('[data-bt-product]');
        if(prod){
          var sel=prod.querySelector('[data-bt-variant]'), ar=prod.querySelector('[data-bt-area]'), v=null;
          if(sel&&sel.offsetParent!==null){try{v=JSON.parse(sel.value);}catch(err2){}}
          if(v){item.variantLabel=v.label||'';item.sku=v.sku||'';item.note='';if(typeof v.price==='number'){item.unitPrice=v.price;item.priceFrom=false;}if(v.m2PerBox){item.m2PerBox=v.m2PerBox;}}
          if(ar&&ar.offsetParent!==null&&parseFloat(ar.value)>0){item.m2=parseFloat(ar.value);item.wastage=true;}
        }
        if(add(item)){
          var q=document.querySelector('.bt-qv0'); if(q){q.checked=true;}
          if(document.querySelector('[data-bt-cart-page]')){
            e.preventDefault(); flash('Added to your enquiry');
            var top=document.querySelector('[data-bt-cart-page] [data-bt-cart-lines]'); if(top&&top.scrollIntoView){try{top.scrollIntoView({behavior:'smooth',block:'start'});}catch(err3){top.scrollIntoView();}}
          }else if(open('Added to your enquiry')){e.preventDefault();}
        }
      }
      return;
    }
    if(t.closest('[data-bt-cart-open]')){ if(!document.querySelector('[data-bt-cart-page]')&&open()){e.preventDefault();} return; }
    var cl=t.closest('[data-bt-cart-clear]');
    if(cl){
      if(cl.getAttribute('data-armed')){clear();cl.removeAttribute('data-armed');cl.textContent=cl.getAttribute('data-label')||'Clear cart';}
      else{cl.setAttribute('data-label',cl.textContent);cl.setAttribute('data-armed','1');cl.textContent='Tap again to clear';setTimeout(function(){if(cl.getAttribute('data-armed')){cl.removeAttribute('data-armed');cl.textContent=cl.getAttribute('data-label');}},4000);}
      return;
    }
    if(t.closest('[data-bt-brief-open]')){ if(briefOpen()){e.preventDefault();} return; }
    var x=t.closest('[data-bt-remove]'); if(x){var id=lineId(x);if(id){remove(id);}return;}
    var s=t.closest('[data-bt-step]');
    if(s){
      var sid=lineId(s),lines=read(),i=find(lines,sid);
      if(i>=0){var u=Math.max(1,(parseInt(lines[i].units,10)||1)+parseInt(s.getAttribute('data-bt-step'),10));update(sid,{units:u});refreshLine(sid);}
    }
  });
  document.addEventListener('input',function(e){
    var t=e.target; if(!t||!t.matches){return;}
    if(t.matches('[data-bt-m2]')){var id=lineId(t);if(id){var v=parseFloat(t.value);update(id,{m2:v>0?v:null});refreshLine(id);}}
  });
  document.addEventListener('change',function(e){
    var t=e.target; if(!t||!t.matches){return;}
    if(t.matches('[data-bt-waste]')){var id=lineId(t);if(id){update(id,{wastage:t.checked});refreshLine(id);}}
    else if(t.matches('.bt-header .bt-bf .bt-p, .bt-header .bt-bf .bt-nd')){briefPrune(t.closest('.bt-bf'));}
    else if(t.matches('[data-bt-enquiry-form] input[name="fulfilment"]')){
      var del=/delivery/i.test(t.value)&&t.checked, ff=t.closest('[data-bt-enquiry-form]');
      Array.prototype.slice.call(ff.querySelectorAll('[name="delivery_address"],[name="delivery_suburb"]')).forEach(function(i){i.required=del;});
    }
    else if(t.matches('.bt-header .bt-toggle')){
      lock();
      if(t.checked&&t.classList.contains('bt-brief-toggle')){briefSync();}
      if(t.checked&&t.classList.contains('bt-search-toggle')){setTimeout(function(){var i=document.querySelector('.bt-header .bt-search input');if(i){i.focus();}},80);}
    }
  });
  document.addEventListener('keydown',function(e){
    var t=e.target;
    if(e.key==='Escape'){
      var openOnes=all('.bt-header .bt-nav-toggle:checked, .bt-header .bt-search-toggle:checked, .bt-header .bt-brief-toggle:checked');
      openOnes.forEach(function(c){c.checked=false;});
      close(); lock(); return;
    }
    if((e.key==='Enter'||e.key===' ')&&t&&t.matches&&t.matches('.bt-header label[role="button"]')){
      if(window.getComputedStyle&&getComputedStyle(t).pointerEvents==='none'){e.preventDefault();return;}e.preventDefault();t.click();return;}
    if(e.key==='Tab'){
      var d=document.querySelector('.bt-header .bt-cart-toggle:checked~.bt-drawer'); if(!d){return;}
      var f=Array.prototype.slice.call(d.querySelectorAll('a[href],button,input,label[tabindex]')).filter(function(n){return n.offsetParent!==null;});
      if(!f.length){return;}
      var first=f[0],last=f[f.length-1];
      if(!d.contains(document.activeElement)){e.preventDefault();first.focus();}
      else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}
      else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}
    }
  });
  /* Car Park Sale: hide the sale callouts once the day has passed (Sydney time) */
  if(Date.now()>Date.UTC(2026,11,12,13,0,0)){document.documentElement.classList.add('bt-sale-over');}
  /* checkout: copy the cart into the form, remember what was sent for the thank you page */
  var SENT='bt_enquiry_sent_v1';
  document.addEventListener('submit',function(e){
    var f=e.target; if(!f||!f.matches||!f.matches('[data-bt-enquiry-form]')){return;}
    var lines=read(); fields(lines);
    try{sessionStorage.setItem(SENT,JSON.stringify({lines:lines,total:lines.length?estTotal(lines):''}));}catch(err){}
  },true);
  function thanks(){
    var box=document.querySelector('[data-bt-thanks]'); if(!box){return;}
    var sent=null; try{sent=JSON.parse(sessionStorage.getItem(SENT)||'null');}catch(err){}
    if(!sent){return;}
    try{sessionStorage.removeItem(SENT);}catch(err2){}
    if(sent.lines&&sent.lines.length){
      all('[data-bt-thanks-list]').forEach(function(ul){ul.innerHTML=sent.lines.map(sumHtml).join('');});
      all('[data-bt-thanks-total]').forEach(function(n){n.textContent=sent.total||'On enquiry';});
      all('[data-bt-thanks-sent]').forEach(function(n){n.hidden=false;});
    }
    clear();
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',thanks);}else{thanks();}
  window.addEventListener('storage',function(e){if(!e.key||e.key===KEY){render();}});
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',render);}else{render();}
  window.addEventListener('pageshow',render);

  window.BTCart={
    key:KEY,get:read,add:add,update:function(id,p){update(id,p);render();},remove:remove,clear:clear,
    count:function(){return read().length;},calc:calc,money:money,open:open,close:close,render:render,brief:briefOpen,
    on:function(fn){if(typeof fn==='function'){subs.push(fn);}}
  };
})();

/* Bonnyrigg Tiles: page interactions (bt-site.js, part 2 of 3)
   Everything here is progressive enhancement. Tabs, quick view, the carousel and the
   room preview already work with CSS alone; this adds keyboard support, the box
   calculator, carousel autoplay and swipe, and pointer tilt. Listeners are delegated. */
(function(){
  if(window.__btUi){return;} window.__btUi=1;
  document.documentElement.classList.add('bt-js');
  var reduce=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  var fine=!!(window.matchMedia&&window.matchMedia('(hover: hover) and (pointer: fine)').matches);
  function all(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s));}
  function money(n){var p=(Math.round(n*100)/100).toFixed(2).split('.');return '$'+p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',')+'.'+p[1];}

  /* quick view: keyboard open and close, focus handling */
  var lastFocus=null;
  function qvOpen(){return document.querySelector('.bt-qv:not(.bt-qv0):checked');}
  function qvClose(){
    var z=document.querySelector('.bt-qv0'); if(z&&!z.checked){z.checked=true;if(lastFocus&&lastFocus.focus){try{lastFocus.focus();}catch(e){}}}
  }
  document.addEventListener('keydown',function(e){
    var t=e.target;
    if(e.key==='Escape'&&qvOpen()){qvClose();return;}
